{"file_path":"src/policies.js","content":"/**
 * A token bucket policy. Tokens are tracked internally in units scaled by
 * `per` so that the fractional refill `refill * elapsed / per` is always an
 * exact integer, never a rounded approximation.
 */
export class Bucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.capacityScaled = capacity * per
    this.states = new Map()
  }

  advance(key, tick) {
    let state = this.states.get(key)
    if (!state) {
      state = { scaled: this.capacityScaled, lastTick: tick }
      this.states.set(key, state)
      return
    }
    const elapsed = tick - state.lastTick
    if (elapsed > 0n) {
      state.scaled += this.refill * elapsed
      if (state.scaled > this.capacityScaled) state.scaled = this.capacityScaled
    }
    state.lastTick = tick
  }

  canAllow(key) {
    return this.states.get(key).scaled >= this.per
  }

  record(key) {
    this.states.get(key).scaled -= this.per
  }
}

/**
 * A sliding window policy. Remembered ticks for a key are always recorded in
 * non-decreasing order, so pruning from the front is enough to drop entries
 * that have fallen out of the window.
 */
export class Window {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  advance(key, tick) {
    let state = this.states.get(key)
    if (!state) {
      state = { ticks: [], lastTick: tick }
      this.states.set(key, state)
    } else {
      state.lastTick = tick
    }
    const threshold = tick - this.span
    while (state.ticks.length > 0 && state.ticks[0] <= threshold) state.ticks.shift()
  }

  canAllow(key) {
    return BigInt(this.states.get(key).ticks.length) < this.limit
  }

  record(key) {
    const state = this.states.get(key)
    state.ticks.push(state.lastTick)
  }
}
"}

