import { Bucket, Window } from './policies.js'

const NAME_RE = /^[A-Za-z0-9_./:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

function requireName(token, lineNumber, kind) {
  if (!NAME_RE.test(token)) throw new CliError(lineNumber, `invalid ${kind} ${token}`)
}

function requireInt(token, fieldName, min, lineNumber) {
  if (!INT_RE.test(token) || BigInt(token) < min) {
    throw new CliError(lineNumber, `${fieldName} must be an integer of at least ${min}`)
  }
  return BigInt(token)
}

function requireNotAfterEvent(firstEventSeen, lineNumber) {
  if (firstEventSeen) throw new CliError(lineNumber, 'declarations must come before the first event')
}

function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function findRoute(routes, key) {
  let best = null
  for (const [prefix, policyNames] of routes) {
    if (key.startsWith(prefix) && (best === null || prefix.length > best.prefix.length)) {
      best = { prefix, policyNames }
    }
  }
  return best
}

/**
 * Parses the limiter file and replays every event against it, returning the
 * full record of what happened so callers can format it for either mode.
 */
export function runLimiter(input) {
  const lines = splitLines(input)
  const policies = new Map()
  const routes = new Map()
  let firstEventSeen = false
  let lastTick = null

  const replayEntries = []
  const summary = new Map()
  let totalAllowed = 0n
  let totalDenied = 0n

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket') {
      if (tokens.length !== 5) {
        throw new CliError(lineNumber, 'expected bucket <name> <capacity> <refill> <per>')
      }
      requireNotAfterEvent(firstEventSeen, lineNumber)
      const [, name, capTok, refillTok, perTok] = tokens
      requireName(name, lineNumber, 'policy name')
      const capacity = requireInt(capTok, 'capacity', 1n, lineNumber)
      const refill = requireInt(refillTok, 'refill', 0n, lineNumber)
      const per = requireInt(perTok, 'per', 1n, lineNumber)
      if (policies.has(name)) throw new CliError(lineNumber, `policy ${name} is declared twice`)
      policies.set(name, new Bucket(capacity, refill, per))
    } else if (directive === 'window') {
      if (tokens.length !== 4) {
        throw new CliError(lineNumber, 'expected window <name> <limit> <span>')
      }
      requireNotAfterEvent(firstEventSeen, lineNumber)
      const [, name, limitTok, spanTok] = tokens
      requireName(name, lineNumber, 'policy name')
      const limit = requireInt(limitTok, 'limit', 0n, lineNumber)
      const span = requireInt(spanTok, 'span', 1n, lineNumber)
      if (policies.has(name)) throw new CliError(lineNumber, `policy ${name} is declared twice`)
      policies.set(name, new Window(limit, span))
    } else if (directive === 'route') {
      if (tokens.length < 3) {
        throw new CliError(lineNumber, 'expected route <prefix> <policy>...')
      }
      requireNotAfterEvent(firstEventSeen, lineNumber)
      const prefix = tokens[1]
      requireName(prefix, lineNumber, 'route prefix')
      const policyNames = tokens.slice(2)
      for (const name of policyNames) {
        requireName(name, lineNumber, 'policy name')
        if (!policies.has(name)) throw new CliError(lineNumber, `unknown policy ${name}`)
      }
      if (routes.has(prefix)) throw new CliError(lineNumber, `prefix ${prefix} is routed twice`)
      routes.set(prefix, policyNames)
    } else if (directive === 'event') {
      if (tokens.length !== 3) {
        throw new CliError(lineNumber, 'expected event <tick> <key>')
      }
      firstEventSeen = true
      const [, tickTok, keyTok] = tokens
      const tick = requireInt(tickTok, 'tick', 0n, lineNumber)
      requireName(keyTok, lineNumber, 'key')
      if (lastTick !== null && tick < lastTick) {
        throw new CliError(lineNumber, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick

      const route = findRoute(routes, keyTok)
      let allowed = true
      let denyPolicy = null

      if (route !== null) {
        const policyObjs = route.policyNames.map((name) => policies.get(name))
        for (const policy of policyObjs) policy.advance(keyTok, tick)
        for (let p = 0; p < policyObjs.length; p++) {
          if (!policyObjs[p].canAllow(keyTok)) {
            allowed = false
            denyPolicy = route.policyNames[p]
            break
          }
        }
        if (allowed) {
          for (const policy of policyObjs) policy.record(keyTok)
        }
      }

      replayEntries.push({ tick, key: keyTok, allowed, denyPolicy })
      if (!summary.has(keyTok)) summary.set(keyTok, { allowed: 0n, denied: 0n })
      const stats = summary.get(keyTok)
      if (allowed) {
        stats.allowed += 1n
        totalAllowed += 1n
      } else {
        stats.denied += 1n
        totalDenied += 1n
      }
    } else {
      throw new CliError(lineNumber, `unknown directive ${directive}`)
    }
  }

  return { replayEntries, summary, totalAllowed, totalDenied }
}
"}

