/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { CliError } from './errors.js'
import { runLimiter } from './simulate.js'

function formatReplay({ replayEntries }) {
  const lines = []
  for (const entry of replayEntries) {
    if (entry.allowed) {
      lines.push(`${entry.tick} ${entry.key} allow\n`)
    } else {
      lines.push(`${entry.tick} ${entry.key} deny ${entry.denyPolicy}\n`)
    }
  }
  return lines
}

function formatSummary({ summary, totalAllowed, totalDenied }) {
  const lines = []
  const keys = Array.from(summary.keys()).sort()
  for (const key of keys) {
    const stats = summary.get(key)
    lines.push(`${key} allowed=${stats.allowed} denied=${stats.denied}\n`)
  }
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}\n`)
  return lines
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }
  const mode = args[0]
  const input = readFileSync(0, 'utf8')

  let result
  try {
    result = runLimiter(input)
  } catch (err) {
    if (err instanceof CliError) {
      process.stderr.write(`error: line ${err.line}: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const lines = mode === 'replay' ? formatReplay(result) : formatSummary(result)
  process.stdout.write(lines.join(''))
  process.exit(0)
}

main()
"}

